'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
DATA.questions.push(...V2.questions);
const LES=new Map(DATA.lessons.map(l=>[l.id,l])),PROB=new Map([...DATA.problems,...VERSION_D.extraCases,...NEURO_WORKED.problems].map(p=>[p.id,p]));
const KEY='bme423-studio-v1';let state={notes:{},read:[],missed:[],attempts:[],practice:{},drafts:{},checks:[],theme:'light',font:18,side:false,examDone:{},scriptVersion:'B',questionVersion:'D'};try{state={...state,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{}
let view='home',selectedModule=2,selectedLesson='start',studyGroup=null,selectedProblem='mean',problemTopic='all',selectedNeuroProblem='neuro-d-hw2-cognition',neuroTopic='all',quiz=null,viewer=null,covered=false,examId='A';const shown=new Set(),hints={};
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#saveStatus').textContent='Saved in this browser';return true}catch{$('#saveStatus').textContent='Storage unavailable · keep this tab open';return false}}
function applyAppearance(){document.documentElement.dataset.mode=state.theme;document.documentElement.style.setProperty('--font',state.font+'px');document.body.classList.toggle('focus',state.side);document.querySelectorAll('[data-theme]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.theme===state.theme)));$('#toggleSide').textContent=state.side?'Open sidebar':'Close sidebar'}
const NAV=[['home','Start & five-day plan'],['learnNow','Learn these methods'],['checkNow','Check understanding'],['minimum','If time is short · know these'],['guidance','What he emphasized'],['core','Must know · core review'],['path','Learn from the beginning'],['worked','Worked examples'],['neuroWorked','Neuroscience worked examples'],['practice','Practice problems'],['quizzes','Lecture quizzes & tests'],['mock','90-minute practice exams'],['calculator','TI‑84 programs'],['formulas','Formula shortcuts & test chooser'],['sheets','Four-page notes · Version 6'],['tables','Statistical tables'],['rlab','Read R output & table values'],['homework','Homework method map'],['missed','Missed & uncertain'],['sources','Sources & coverage']];
function nav(){$('#workNav').innerHTML=NAV.map(([v,t])=>`<button data-view="${v}" class="${view===v?'active':''}">${t}</button>`).join('');$('#moduleNav').innerHTML=DATA.modules.map(m=>`<button data-module="${m.id}" class="${view==='module'&&selectedModule===m.id?'active':''}">Session ${m.id} · ${esc(m.title)}</button>`).join('')}
function go(v){if('speechSynthesis'in window)speechSynthesis.cancel();view=v;document.body.classList.remove('expanded');render();window.scrollTo(0,0)}
function note(key,label='Notes'){return `<div class="notes"><label>${esc(label)}<small>Saved in this browser</small><textarea rows="1" data-note="${esc(key)}" aria-label="${esc(label)}" placeholder="One reminder, one line of working, or a question…">${esc(state.notes[key]||'')}</textarea></label></div>`}
function sizeNote(el){const old=Number(el.dataset.auto)||0,current=parseFloat(el.style.height)||0;if(old&&Math.abs(current-old)>2)el.dataset.manual=String(current);el.style.height='0px';const h=Math.max(46,Number(el.dataset.manual)||0,el.scrollHeight+2);el.style.height=Math.min(650,h)+'px';el.dataset.auto=String(Math.min(650,h))}
function image(mid,page){return `assets/session${mid}/${page}.webp`}
function scope(){return `<div class="scope"><strong>${DATA.exam.date} · ${DATA.exam.time}</strong><br>${DATA.exam.count}. Through Session 13. Session 14 and hand-calculated sum-of-squares ANOVA are excluded. Balanced ANOVA only.<br><strong>Bring:</strong> two double-sided 8.5″×11″ note sheets, a calculator, and the course’s unannotated z, t, F, and χ² tables. Tables will not be provided.</div>`}
function checklist(id,text){return `<label class="checkline"><input type="checkbox" data-checklist="${id}" ${state.checks.includes(id)?'checked':''}> ${text}</label>`}
const DAYS=[['Wednesday · get started',['Read the notation guide and work the mean/SD/SEM example.','Classify measurements and categories.','Work the discrete probability table without looking at the solution.'],['start','summary','classification','pmf']],['Thursday · probability',['Work the continuous-density example one line at a time.','Practise CDFs, expectations, and variance.','Do Normal left/right/between probabilities and one percentile.'],['density','integrate','ccdf','cexpect','normalprob','normalquant']],['Friday · sample means and t tests',['Separate individual SD from SEM.','Work one one-sample and one pooled two-sample t test.','Review Homework 2 methods; submit Friday by 5 PM. Review solutions when posted (he expects early Saturday).'],['sampling','onet','pooledt']],['Saturday · ANOVA and categorical tests',['Work balanced ANOVA, then Bonferroni and Holm.','Build expected-count tables, including Yates for 2×2.','Work goodness of fit and read R output.'],['anova','posthoc','bonferroni','holm','zprop','chi','gof']],['Sunday · integrate and rehearse',['Work RR, absolute risk change, NNT/NNH, and OR.','Take a 90-minute written practice exam, then correct the work.','Print the four-page notes pack; practise using the separate course tables.'],['risk','nnt','odds','rcode']],['Monday · short warm-up',['Review the test chooser and a few past errors.','Pack calculator, two double-sided note sheets, and unannotated tables.','Use labels and one calculation per line during the exam.'],['choose']]];
function home(){return `<div class="hero"><span class="tag">BME423 MIDTERM WORKSPACE</span><h1>Understand the question.<br>Then do one small step.</h1><p>Build the methods from the beginning with clear explanations, original slides, fully worked examples, and additional practice problems. Every intermediate value stays visible.</p><div class="row"><button class="primary" data-lesson="start" data-study-group="0">Start from zero</button><button data-view="worked">Work an example</button><button data-view="minimum">If time is short</button><button data-view="core">Core review</button></div></div>${rapidEntry()}${scope()}<div class="grid"><div class="card"><div class="metric">${state.read.length}</div><p>Topics marked read</p></div><div class="card"><div class="metric">${Object.values(state.practice).filter(p=>p.correct).length}</div><p>Numerical answers checked correctly</p></div><div class="card"><div class="metric">${state.missed.length}</div><p>Quiz questions to revisit</p></div></div><h2>Study route to Monday</h2><p class="muted">Use 25-minute blocks with short breaks. Start with the listed example, try it again covered, then do a few new numbers. Add a block where the work still feels uncertain.</p>${DAYS.map(([title,actions,topics],i)=>`<div class="card" id="study-group-${i}"><h3>${title}</h3>${actions.map((a,j)=>checklist('day'+i+'-'+j,esc(a))).join('')}<div class="row">${topics.map(k=>`<button class="tiny" data-lesson="${k}" data-study-group="${i}">${esc(LES.get(k).title)}</button>`).join('')}</div></div>`).join('')}`}
function scriptSelector(){return `<label class="script-select">Teaching version <select data-script-version aria-label="Teaching version"><option value="A" ${state.scriptVersion==='A'?'selected':''}>Original · Version A</option><option value="B" ${state.scriptVersion==='B'?'selected':''}>Version B · intuition → full work → shortcut</option><option value="C" ${state.scriptVersion==='C'?'selected':''}>Version C · slide-by-slide lecture + full work</option></select></label>`}
function slideScript(mid,page){if(state.scriptVersion!=='C'||mid===undefined||page===undefined)return null;const s=VERSION_C.slides[mid+':'+page];if(!s)throw new Error('Missing Version C slide '+mid+':'+page);return s}
function lectureText(mid,page){const s=slideScript(mid,page);return s?`<section class="slide-lecture teaching" data-slide-lecture="${mid}:${page}" aria-label="Slide teaching explanation">${teachingParagraphs(s.paragraphs,EQUATION_GUIDE.slides[mid+':'+page]||{},HYPOTHESES.slides[mid+':'+page]||null)}</section>`:''}
function lessonText(l,mid,page){const isB=state.scriptVersion!=='A',b=V2.B[l.id],h=teachingHypothesis(l.id,mid,page),isC=!!slideScript(mid,page);return lectureText(mid,page)+(isC?hypothesisPair(h):'')+`<div class="teaching">${isB?'<h3>Understand what changes and why</h3>':''}${teachingParagraphs(isB?b.paragraphs:l.paragraphs,EQUATION_GUIDE.lessons[l.id]||{},h)}${!isC?hypothesisPair(h):''}</div><details class="formula-reference"><summary>Formula reference · symbol meanings</summary><div class="equations">${formulaHTML(l)}</div><p class="symbol-key">${rich(b.legend)}</p></details>${V2.worked[l.id]?`<h3>Apply it · write the work in order</h3>${sourceWorked(V2.worked[l.id])}`:''}${l.shortcut?`<div class="shortcut"><strong>Shorter method</strong><p>${rich(l.shortcut)}</p></div>`:''}${l.watch?`<p class="watch">${rich(l.watch)}</p>`:''}<div class="row" style="margin-top:16px"><button class="primary" data-problem="${lessonExample(l)}">Show every step · practice example</button><button data-practice-topic="${l.id}">Try a problem</button><button class="tiny" data-topic-quiz="${l.id}">Quiz this topic</button></div>`}
function readBox(l){return `<label class="checkline"><input type="checkbox" data-read="${l.id}" ${state.read.includes(l.id)?'checked':''}> Mark this topic read</label>`}
function lessonCard(l,mid,page,open=false){const s=slideScript(mid,page);return `<details class="lesson ${l.core?'core-border':''}" ${open?'open':''} data-search="${esc((l.title+' '+l.paragraphs.join(' ')).toLowerCase())}"><summary>${s?`${page}. ${esc(s.title)}`:esc(l.title)} ${l.core?'<span class="core-tag">Must know · core review</span>':''}</summary><div class="pair"><div>${lessonText(l,mid,page)}${readBox(l)}${note('s'+mid+':'+page)}</div><div class="slide-wrap"><img class="sourcepic" loading="lazy" src="${image(mid,page)}" alt="Original Session ${mid}, PDF page ${page}: ${esc(l.title)}" data-zoom><p class="caption">Original Session ${mid}, PDF page ${page} · click to enlarge</p><button data-open-slide="${mid}:${page}">Expand visual + transcript</button></div></div></details>`}
function pathScreen(core=false){const ls=DATA.lessons.filter(l=>core?l.core:l.id!=='power'&&l.id!=='anovaSS');return `<span class="${core?'core-tag':'tag'}">${core?'REVIEW-ALIGNED PRIORITIES':'BEGIN WITH THE BASICS'}</span><h1>${core?'Must know · core review':'Learn from the beginning'}</h1><p class="muted">${core?'Based on Session 15 and the homework methods.':'Follow the sequence; each topic links to a complete worked calculation.'} The original slides stay beside the explanations.</p><div class="row"><button data-viewer-set="${core?'core':'path'}">Expand visual + transcript · full collection</button><button id="openTopics">Open topics</button><button id="closeTopics">Close topics</button></div>${scriptSelector()}<input id="topicSearch" class="search" placeholder="Find a method, term, or formula…" aria-label="Search topics">${ls.map((l,i)=>lessonCard(l,l.refs[0].module,l.refs[0].page,i===0)).join('')}`}
function studySequence(){const group=Number.isInteger(studyGroup)?DAYS[studyGroup]:null;if(!group)return null;const index=group[2].indexOf(selectedLesson);return index<0?null:{group,index,topics:group[2]}}
function studyNavigation(){const route=studySequence();if(!route)return '';const {group,index,topics}=route,previous=LES.get(topics[index-1]),next=LES.get(topics[index+1]);return `<div class="card study-sequence" role="group" aria-label="Study group navigation"><p class="small muted">${esc(group[0])} · Topic ${index+1} of ${topics.length}${!next?' · Last topic in this group':''}</p><div class="row"><button data-study-step="-1" aria-label="${esc(previous?'Previous: '+previous.title:'Previous topic')}" ${previous?'':'disabled'}>← Previous</button><button class="primary" data-study-step="1" aria-label="${esc(next?'Next: '+next.title:'Next topic')}" ${next?'':'disabled'}>Next →</button><button data-plan-group="${studyGroup}">Back to plan</button></div>${next?`<p class="small muted">Next: ${esc(next.title)}</p>`:''}</div>`}
function moveStudyTopic(step){const route=studySequence();if(!route||![1,-1].includes(step))return;const next=route.topics[route.index+step];if(!next)return;selectedLesson=next;go('lesson')}
function lessonScreen(){const l=LES.get(selectedLesson),ref=l.refs[0];return `<span class="${l.core?'core-tag':'tag'}">${l.core?'Must know · core review':'FOUNDATION / REFERENCE'}</span><h1>${esc(l.title)}</h1>${studyNavigation()}${scriptSelector()}<div class="pair"><div>${lessonText(l,ref.module,ref.page)}${readBox(l)}${note('s'+ref.module+':'+ref.page)}</div><div><img class="sourcepic" data-zoom src="${image(ref.module,ref.page)}" alt="Original lecture slide for ${esc(l.title)}"><p class="caption">Session ${ref.module}, PDF page ${ref.page}</p><button data-open-slide="${ref.module}:${ref.page}">Expand visual + transcript</button></div></div><h2>Other source locations</h2><div class="row">${[...new Set(l.refs.map(r=>r.module))].map(mid=>`<button data-module="${mid}">Session ${mid}</button>`).join('')}</div>${studyNavigation()}`}
function moduleScreen(){const m=DATA.modules.find(m=>m.id===selectedModule);return `<span class="tag">${m.optional?'OUTSIDE THIS MIDTERM':'INDIVIDUAL COLLECTION'} · SESSION ${m.id}</span><h1>${esc(m.title)}</h1>${m.optional?'<div class="scope">The review explicitly excludes this lecture from the midterm. Original slides and a reference explanation remain available.</div>':''}<div class="row"><button data-module-view="normal">Visual + transcript</button><button class="primary" data-module-view="expanded">Expand visual + transcript</button>${!m.optional?`<button data-quiz-module="${m.id}">Lecture quiz</button>`:''}<a href="sources/${m.source}.pdf" target="_blank" rel="noopener">Original PDF · ${m.count} pages</a></div>${scriptSelector()}<p class="small muted">${state.scriptVersion==='C'?'Every slide has its own teaching explanation, followed by the full Version B material.':'Explanations are grouped by topic. Every original PDF page is available in the visual + transcript viewer.'}</p>${state.scriptVersion==='C'?makeModuleSlides(m.id).map((s,i)=>lessonCard(LES.get(s.topic),m.id,s.page,i===0)).join(''):m.sections.map((s,i)=>{const l=LES.get(s.topic);return `<div class="small muted">Original PDF pages ${s.pages[0]}–${s.pages.at(-1)}</div>`+lessonCard(l,m.id,s.pages[0],i===0)}).join('')}`}
function makeModuleSlides(mid){const m=DATA.modules.find(m=>m.id===Number(mid));return m.sections.flatMap(s=>s.pages.map(page=>({module:m.id,page,topic:s.topic,label:'Session '+m.id+' · '+page+' · '+LES.get(s.topic).title})))}
function openViewer(slides,index=0,expanded=true,back=view){viewer={slides,index,expanded,back};covered=false;view='viewer';render();window.scrollTo(0,0)}
function questionVersionSelector(){return `<label class="question-version">Question version<select data-question-version-select aria-label="Question version"><option value="D" ${versionD()?'selected':''}>Version D · full homework-style problems</option><option value="C" ${!versionD()?'selected':''}>Previous question wording</option></select></label>`}
function viewerScreen(){const s=viewer.slides[viewer.index],l=LES.get(s.topic);return `<div class="viewer-controls">${scriptSelector()}${questionVersionSelector()}<button id="exitViewer">✕ Close</button><button id="prevSlide" ${viewer.index===0?'disabled':''}>← Previous</button><select id="slideSelect" aria-label="Visual and transcript section">${viewer.slides.map((x,i)=>`<option value="${i}" ${i===viewer.index?'selected':''}>${i+1}. ${esc(slideScript(x.module,x.page)?'Session '+x.module+' · '+x.page+' · '+slideScript(x.module,x.page).title:x.label)}</option>`).join('')}</select><button id="nextSlide" ${viewer.index===viewer.slides.length-1?'disabled':''}>Next →</button><button id="coverTranscript">${covered?'Reveal transcript':'Hide transcript'}</button><button id="speak">Read aloud</button><button id="stopSpeak">Stop audio</button><button data-font="-1">A−</button><button data-font="1">A+</button></div><div class="viewer-pair"><div class="transcript">${l.core?'<span class="core-tag">Must know · core review</span>':''}<p class="small muted">${viewer.index+1} / ${viewer.slides.length} · Session ${s.module} · original PDF page ${s.page}</p><h2>${esc(slideScript(s.module,s.page)?.title||l.title)}</h2>${covered?'<div class="covered">Try explaining the idea from the visual.<p><button id="revealTranscript">Reveal transcript</button></p></div>':`<div id="spoken">${lessonText(l,s.module,s.page)}</div>`}${readBox(l)}${note('s'+s.module+':'+s.page)}</div><div class="slide-wrap"><img class="sourcepic" data-zoom src="${image(s.module,s.page)}" alt="Session ${s.module}, original page ${s.page}"><p class="caption">Original source visual · click to enlarge</p></div></div>`}
function stepsHTML(p,count=problemSteps(p).length){const flow=problemSteps(p),hypothesis=problemHypothesis(p),hasNull=flow.some(s=>s.math.some(isNullStatement));if(!flow.length)throw Error('Missing connected solution '+p.id);return `<div class="steps" data-integrated-problem="${esc(p.id)}">${count&&hypothesis&&!hasNull?hypothesisPair(hypothesis):''}${flow.slice(0,count).map((s,i)=>`<div class="step" data-integrated-step="${i}"><h4>${i+1}. ${esc(s.label)}</h4><div class="worked-math">${stepGeneralHTML(p,i)}${s.math.map(t=>workedEquation(t,hypothesis)).join('')}${stepReferenceHTML(p,i)}${s.text.map(t=>`<p>${rich(t)}</p>`).join('')}${workedFigure(s.figure)}</div>${!versionD()&&p.steps[workedSolutionContext(p).indices[i]]?.why?`<p>${rich(p.steps[workedSolutionContext(p).indices[i]].why)}</p>`:''}</div>`).join('')}</div>`}
function problemHTML(p,worked=false,locked=false,questionHTML=null){const record=state.practice[p.id],visible=!locked&&(worked||shown.has(p.id)),count=visible?problemSteps(p).length:!locked?(hints[p.id]||0):0;return `<div class="card"><span class="tag">${esc(versionD()&&locked?'Written study case':LES.get(p.topic).title)}</span>${questionHTML??problemQuestionHTML(p,worked)}${!locked?`<div class="answerbox"><label for="ans-${p.id}">Requested answer ${p.units?'('+esc(p.units)+')':''}</label><input id="ans-${p.id}" data-response="${p.id}" aria-label="Answer for ${esc(p.title)}" inputmode="decimal" placeholder="Number or fraction" value="${esc(state.drafts[p.id]||'')}"><button class="primary" data-grade="${p.id}">Check the answer</button></div>${record?`<div class="feedback ${record.correct?'':'wrong'}" role="status">${record.correct?'✓ That numerical answer checks out.':record.error?'Enter a number, fraction, or percentage.':'Not quite yet. Check the labeled inputs and your next step.'}${record.revealed?' Solution has been viewed; try again later without it.':''}</div>`:''}<div class="row"><button data-hint="${p.id}">Show the next step</button><button data-solution="${p.id}">Show all work</button><button data-lesson="${p.topic}">Review this method</button></div>`:''}${count?stepsHTML(p,count):''}${visible?`<div class="shortcut"><strong>Shorter method</strong><br>${rich(p.shortcut)}</div>`:''}${note('problem:'+p.id,'Working / notes')}<p class="caption">${esc(p.source)}${!locked?' · Numerical checks allow ordinary rounding; keep extra digits in intermediate steps.':''}</p></div>`}
function problemPool(){return versionD()?[...VERSION_D.extraCases,...DATA.problems]:DATA.problems}
function questionPool(){return versionD()?[...DATA.questions,...VERSION_D.extraQuizItems]:DATA.questions}
function lessonExample(l){return versionD()?(VERSION_D.examples[l.id]||l.example):l.example}
function eligibleProblems(){return problemPool().filter(p=>problemTopic==='all'||p.topic===problemTopic)}
function practiceScreen(worked){let ps=eligibleProblems();if(!ps.length)ps=problemPool();let p=ps.find(p=>p.id===selectedProblem)||ps[0];selectedProblem=p.id;return `<h1>${worked?'Worked examples · every step':'Practice problems'}</h1><p class="muted">${worked?'Read one line, explain it, then cover the work and try again.':'Set up the method yourself, keep your working below, then check the requested numerical answer. You can reveal one step at a time.'}</p><div class="row"><select id="problemTopic" aria-label="Practice topic"><option value="all">All topics</option>${DATA.lessons.filter(l=>problemPool().some(p=>p.topic===l.id)).map(l=>`<option value="${l.id}" ${problemTopic===l.id?'selected':''}>${esc(l.title)}</option>`).join('')}</select><select id="problemSelect" aria-label="Worked example or practice problem">${ps.map(p=>`<option value="${p.id}" ${p.id===selectedProblem?'selected':''}>${esc(p.title)} · ${p.id}</option>`).join('')}</select><button id="newProblem" ${problemPool().filter(x=>x.topic===p.topic).length<2?'disabled':''}>Another problem with this method</button></div>${problemHTML(p,worked)}`}
function formulas(){return `<h1>Formula shortcuts & test chooser</h1><div class="card"><h2>Choose before you calculate</h2><p>Numerical outcome: one sample versus a reference → one-sample t; two independent equal-variance groups → pooled t; three or more balanced groups → ANOVA.</p><p>Categorical outcome: two proportions → corrected z or 2×2 χ²; larger table → contingency χ²; one count list versus target proportions → goodness of fit. Association size → RR / ARR / NNT or OR, according to study design.</p></div>${DATA.lessons.filter(l=>l.formula&&l.id!=='power').map(l=>`<div class="card"><h3>${esc(l.title)}</h3><div class="equations">${formulaHTML(l)}</div><p>${rich(V2.B[l.id].legend)}</p><div class="shortcut">${esc(l.shortcut)}</div><p class="watch">${esc(l.watch)}</p><button data-lesson="${l.id}">Explain it from the beginning</button><button data-problem="${lessonExample(l)}">Worked calculation</button></div>`).join('')}`}
function sheetsOriginal(){return `<div class="no-print"><h1>Four-page notes pack</h1><p>Four sides = two double-sided letter sheets. This pack follows the midterm review. Bring the course’s unannotated tables separately.</p><div class="row"><button class="primary" id="print">Print four sides</button><a href="BME423-four-page-notes.pdf" download>Download the four-page PDF</a></div></div>${DATA.sheets.map(([title,keys])=>`<article class="sheet"><h2>BME423 · ${title}</h2><p class="small">Through Session 13 · balanced ANOVA · two-sided tests unless specified</p><div class="sheet-grid">${keys.map(k=>{const l=LES.get(k);return `<div class="sheet-block"><h3>${esc(l.title)}</h3>${l.formula?`<div class="equations">${formulaHTML(l)}</div>`:''}<p>${esc(l.shortcut||l.paragraphs[0])}</p>${l.symbols?`<p>${rich(V2.B[l.id].legend)}</p>`:''}${l.watch?`<p>${esc(l.watch)}</p>`:''}</div>`}).join('')}</div></article>`).join('')}`}
function sheets(){return `<div class="no-print"><h1>Four-page notes</h1><p><strong>Version 6 · complete worked solutions</strong></p><p>General equations, labeled substitutions, every calculation, and conclusions. Four Letter pages with three columns and 0.3-inch margins on every side.</p><div class="row"><a class="button-link primary" href="BME423-four-page-notes-v6.pdf?v=new-worked-v6" download>Download Version 6 PDF</a><a href="notes-v6.html?v=new-worked-v6" target="_blank">Open Version 6 print view</a></div><p><strong>Version 5 · equations within each worked step</strong></p><div class="row"><a class="button-link primary" href="BME423-four-page-notes-v5.pdf?v=v5-full-algebra" download>Download Version 5 PDF</a><a href="notes-v5.html?v=v5-full-algebra" target="_blank">Open Version 5 print view</a></div><p><strong>Version 4 · equations + full worked methods</strong></p><div class="row"><a class="button-link primary" href="BME423-four-page-notes-v4.pdf?v=course-work-v4" download>Download Version 4 PDF</a><a href="notes-v4.html?v=course-work-v4" target="_blank">Open Version 4 print view</a></div><h2>Version 3 · follow-along solutions</h2><p>Match the question, read the general equation, then follow its substituted numbers through the worked solution, table lookup and conclusion. Four letter-size sides, three columns, and 0.3-inch margins on every side. Print at actual size, with browser headers/footers off.</p><div class="row"><a class="button-link primary" href="BME423-four-page-notes-v3.pdf?v=sheet-sketch-v3" download>Download Version 3 PDF</a><a href="notes-v3.html?v=sheet-sketch-v3" target="_blank">Open Version 3 print view</a><a href="notes-v2.html" target="_blank">Previous Version 2</a><button data-view="sheetsOriginal">Original Version 1</button><button data-view="tables">Open separate tables</button><button id="print">Print four sides</button></div></div><div class="notes-preview">${renderFollowAlongSheet()}</div>`}
function minimum(){return `<span class="core-tag">SHORT PREPARATION ROUTE</span><h1>If time is short, know these</h1><p>Start with probability, then work through the mean and count comparisons. For each method, name what the question asks, reproduce the setup, and write a contextual conclusion. The list follows the professor’s review and homework.</p><div class="row"><button data-view="sheets">Four-page worked notes</button><button data-view="mock">Try the written exam</button><button data-view="guidance">What he emphasized</button><button class="primary" data-view="learnNow">Learn these methods</button><button data-view="checkNow">Check understanding</button></div><div class="scope"><strong>The review’s explicit priorities:</strong> a couple of probability questions; balanced ANOVA with means/SDs supplied; appropriate tests and population nulls; corrected 2×2 comparisons; adjusted pairwise decisions; RR versus OR; interpretation of supplied R output. No code writing.</div>${V2.minimum.map(([k,title],i)=>`<details class="card minimum-item" ${i===0?'open':''}><summary>${i+1}. ${esc(title)}</summary><p>${rich(V2.B[k].paragraphs[0])}</p><p class="symbol-key">${rich(V2.B[k].legend)}</p>${V2.worked[k]?sourceWorked(V2.worked[k]):formulaHTML(LES.get(k))}<div class="row"><button data-lesson="${k}">Full teaching explanation</button><button data-problem="${lessonExample(LES.get(k))}">Practise the method</button></div>${checklist('minimum-'+k,'Set up the problem and explain the answer without looking.')}</details>`).join('')}`}
function guidance(){return `<h1>What he emphasized in the review</h1><p><a href="sources/midterm-review-transcript.txt" target="_blank">Original review transcript</a> · <a href="exam-priorities.json">Evidence-ranking details</a></p>${V2.guidance.map(g=>`<div class="card"><h2>${esc(g.title)}</h2><blockquote>“${esc(g.quote)}”</blockquote><p>${rich(g.detail)}</p></div>`).join('')}<div class="card"><h2>How the study priorities are ranked</h2><p>A transparent evidence model scores explicit transcript emphasis (5), review-page inclusion (3), Homework 1 practice (2), and Homework 2 practice (3). Excluded methods receive zero. These scores rank preparation value; they are not fitted probabilities of unseen questions. All included course content remains available.</p>${V2.priorities.filter(p=>p.score>=10).map(p=>`<p><button data-lesson="${p.topic}">${esc(LES.get(p.topic).title)}</button> <span class="small">review ${p.reviewPages.length?'pp. '+p.reviewPages.join(', '):'discussion'}${p.hw1?' · HW1':''}${p.hw2?' · HW2':''}</span></p>`).join('')}</div>`}
function tables(){return `<h1>Statistical tables</h1><p>These are the original uploaded PDFs, kept unannotated. Bring the z, t, F, and chi-square tables separately from the four notes sides. The two chi-square PDFs are alternative tables of the same distribution; Table 2 is upright and easier to read.</p>${sourceWorked('tables')}<h2>Tables for this midterm</h2>${V2.tables.filter(t=>t.midterm).map(t=>`<div class="card"><h3>${esc(t.name)}</h3><a href="${t.url}" target="_blank">Open</a> · <a href="${t.url}" download>Download original</a></div>`).join('')}<details class="card"><summary>Other uploaded tables · outside the stated midterm methods</summary><p>Uploading these tables does not add rank-based tests to the Session 2–13 exam scope.</p>${V2.tables.filter(t=>!t.midterm).map(t=>`<p><a href="${t.url}" target="_blank">${esc(t.name)}</a></p>`).join('')}</details>`}
function neuroscienceScreen(){
 const pool=NEURO_WORKED.problems,ps=pool.filter(p=>neuroTopic==='all'||p.topic===neuroTopic);
 const p=ps.find(p=>p.id===selectedNeuroProblem)||ps[0];selectedNeuroProblem=p.id;
 return `<h1>Neuroscience worked examples · every step</h1><p class="muted">Read one line, explain it, then cover the work and try again.</p><div class="row"><select id="neuroTopic" aria-label="Neuroscience practice topic"><option value="all">All topics</option>${DATA.lessons.filter(l=>pool.some(p=>p.topic===l.id)).map(l=>`<option value="${l.id}" ${neuroTopic===l.id?'selected':''}>${esc(l.title)}</option>`).join('')}</select><select id="neuroProblemSelect" aria-label="Neuroscience worked example">${ps.map(p=>`<option value="${p.id}" ${p.id===selectedNeuroProblem?'selected':''}>${esc(p.title)}</option>`).join('')}</select><button id="newNeuroProblem" ${pool.filter(x=>x.topic===p.topic).length<2?'disabled':''}>Another problem with this method</button></div>${problemHTML(p,true)}`;
}

function quizMenu(){return `<h1>Lecture quizzes & practice tests</h1><p>Immediate feedback, explanations, and worked-example links. Correct-answer letters never repeat back to back; every answer key is validated before display.</p><div class="row"><button class="primary" data-start="100">100-question combined test</button><button data-start="20">20-question mixed set</button><button data-start="10">10-question warm-up</button></div><p class="small muted">For the exam’s written calculation format, use the separate 90-minute practice exams.</p><div class="grid">${DATA.modules.filter(m=>!m.optional&&m.id!==15).map(m=>{const ks=new Set(m.sections.filter(s=>s.topic!=='anovaSS').map(s=>s.topic));const n=questionPool().filter(q=>ks.has(q.topic)).length;return `<div class="card"><h3>Session ${m.id}</h3><p>${esc(m.title)}</p><button data-quiz-module="${m.id}">${Math.min(30,n)}-question quiz</button><button class="tiny" data-module="${m.id}">Review lecture</button></div>`}).join('')}</div>`}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function shuffleChoiceOrder(length){const order=Array.from({length},(_,i)=>i);for(let i=order.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[order[i],order[j]]=[order[j],order[i]]}return order}
function validateAnswerKey(items){let valid=true,previous=-1;for(const q of items){const position=q.order.indexOf(q.correct);if(position<0||q.order.length!==q.options.length||new Set(q.order).size!==q.options.length||q.order.some(i=>!Number.isInteger(i)||i<0||i>=q.options.length)||position===previous)valid=false;previous=position}return valid}
function prepareQuizItems(questions){const sources=questions.map(q=>{if(q.options.length!==4||!Number.isInteger(q.correct)||q.correct<0||q.correct>=q.options.length)throw Error('Invalid quiz choices');return {...q,options:q.options.map(text=>text.replace(/^(All|None) of the above$/i,(_,word)=>word+' of the other options')),why:q.why.replace(/all of the above/gi,'all of the other options').replace(/none of the above/gi,'none of the other options')}});let candidate=sources.map(q=>({...q,order:shuffleChoiceOrder(q.options.length)}));while(!validateAnswerKey(candidate)){// Reject the key and rebuild. Local rejection avoids exponential retries on long exams.
 candidate=[];for(const q of sources){let order;do{order=shuffleChoiceOrder(q.options.length)}while(candidate.length&&order.indexOf(q.correct)===candidate[candidate.length-1].order.indexOf(candidate[candidate.length-1].correct));candidate.push({...q,order})}}return candidate}

function startQuiz(kind,module=null,topic=null){let pool=questionPool();if(kind==='module'){const m=DATA.modules.find(m=>m.id===Number(module));const keys=new Set(m.sections.filter(s=>s.topic!=='anovaSS').map(s=>s.topic));pool=pool.filter(q=>keys.has(q.topic));pool=shuffle(pool.filter((q,i,a)=>a.findIndex(x=>x.stem===q.stem)===i)).slice(0,30)}else if(kind==='topic')pool=shuffle(pool.filter(q=>q.topic===topic)).slice(0,20);else if(kind==='missed')pool=shuffle(pool.filter(q=>state.missed.includes(q.id)));else if(Number(kind)===100){const groups=[[['random','independent','pmf','dcdf','expect','variance','density','uniform','integrate','ccdf','cexpect','normal','normalprob','normalquant'],35],[['classification','summary','percentile','plots'],10],[['sampling','estimators','linear','distributions'],10],[['choose','hypothesis','anova','pooledt','onet','posthoc','bonferroni','holm'],25],[['binary','zprop','yates','contingency','chi','gof'],10],[['risk','nnt','odds'],6],[['rcode'],4]];const used=new Set();pool=shuffle(groups.flatMap(([ks,n])=>{const items=shuffle(questionPool().filter(q=>ks.includes(q.topic)&&!used.has(q.stem)).filter((q,i,a)=>a.findIndex(x=>x.stem===q.stem)===i)).slice(0,n);items.forEach(q=>used.add(q.stem));return items}))}else pool=shuffle(pool).slice(0,Number(kind));if(!pool.length){go('quizzes');return}quiz={items:prepareQuizItems(pool),index:0,answers:[],finished:false};view='quiz';render();window.scrollTo(0,0)}
function quizScreen(){if(quiz.finished)return quizResults();const q=quiz.items[quiz.index],a=quiz.answers[quiz.index],good=quiz.answers.filter((a,i)=>a&&a.choice===quiz.items[i].correct).length;return `<div class="quiz"><span class="tag">${esc(versionD()?'Version D · clinical and statistical questions':LES.get(q.topic).title)}</span><div class="row" style="justify-content:space-between"><p>Question ${quiz.index+1} / ${quiz.items.length}</p><p>${good} correct</p></div><div class="progress"><div style="width:${100*quiz.answers.filter(Boolean).length/quiz.items.length}%"></div></div><div class="quizstem">${quizQuestionHTML(q)}</div>${versionD()?note('quiz:'+q.id,'Working / notes'):''}<div class="options">${q.order.map((v,i)=>`<button class="option ${a?(v===q.correct?'correct':a.choice===v?'wrong':''):''}" data-answer="${v}" ${a?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span>${rich(q.options[v])}${a&&v===q.correct?' ✓':''}</span></button>`).join('')}</div>${a?`<div class="feedback ${a.choice===q.correct?'':'wrong'}" role="status"><strong>${a.choice===null?'Answer revealed · not scored correct':a.choice===q.correct?'✓ Correct':'Not quite · review the method'}</strong>${quizExplanation(q)}<div class="row"><button data-lesson="${q.topic}">Full teaching explanation</button>${q.problem?`<button data-problem="${q.problem}">Show every calculation step</button>`:''}<button id="uncertain">Mark uncertain</button></div></div>`:''}<div class="row quizfooter"><button id="prevQ" ${quiz.index===0?'disabled':''}>← Previous</button>${!a?'<button id="revealQ">Reveal & learn</button><button id="skipQ">Skip for now</button>':''}<button class="primary" id="nextQ" ${!a?'disabled':''}>${quiz.index===quiz.items.length-1?'Results':'Next →'}</button></div><p class="small muted">A–D or 1–4 selects the matching displayed answer.</p></div>`}
function answer(choice){if(!quiz||quiz.finished||quiz.answers[quiz.index])return;const q=quiz.items[quiz.index];quiz.answers[quiz.index]={choice};const good=choice===q.correct;state.attempts.push({id:q.id,correct:good});state.missed=state.missed.filter(id=>id!==q.id);if(!good)state.missed.push(q.id);save();render()}
function quizResults(){let n=quiz.answers.filter((a,i)=>a&&a.choice===quiz.items[i].correct).length;return `<div class="hero"><span class="tag">PRACTICE RESULTS</span><h1>${n} / ${quiz.items.length} correct</h1><div class="row"><button data-start="missed">Retry missed & uncertain</button><button data-view="quizzes">Another set</button></div></div>${quiz.items.map((q,i)=>`<details class="card"><summary>${quiz.answers[i]?.choice===q.correct?'✓':'○'} ${i+1}. ${esc(LES.get(q.topic).title)}</summary>${quizQuestionHTML(q)}<p><strong>Correct:</strong> ${rich(q.options[q.correct])}</p>${quizExplanation(q)}<button data-lesson="${q.topic}">Review method</button></details>`).join('')}`}
function missed(){return `<h1>Missed & uncertain</h1><p>${state.missed.length} quiz questions queued for another try.</p><button class="primary" data-start="missed" ${!state.missed.length?'disabled':''}>Retry these questions</button>${state.missed.map(id=>questionPool().find(q=>q.id===id)).filter(Boolean).map(q=>`<div class="card">${quizQuestionHTML(q)}<button data-lesson="${q.topic}">Review the method</button>${q.problem?`<button data-problem="${q.problem}">Work the example</button>`:''}</div>`).join('')}`}
function writtenExams(){return versionD()?VERSION_D.writtenExams.map(e=>({...e,questions:e.questions.map((problems,i)=>({title:'Study '+(i+1),problems,rubric:'Check the full population question, equations, calculations and contextual conclusion.'}))})):DATA.exams}
function examStateKey(id){return versionD()?'D-'+id:id}
function mock(){const e=writtenExams().find(e=>e.id===examId),done=state.examDone[examStateKey(e.id)];return `<div class="no-print"><span class="tag">ORIGINAL WRITTEN PRACTICE · NOT AN INSTRUCTOR EXAM</span><h1>${e.title}</h1><p>Eight multi-part questions, with the first three focused on probability. Use 90 minutes, the calculator, and your allowed notes/tables. Write the setup and conclusion as well as the numerical answer.</p><div class="row">${writtenExams().map(x=>`<button data-exam="${x.id}" class="${examId===x.id?'primary':''}">${x.title}</button>`).join('')}<button id="startMock">Start 90-minute timer</button><button class="primary" id="finishMock">${done?'Solutions are open':'Finish & open worked solutions'}</button><button id="resetMock">Hide solutions</button><button id="print">Print this practice</button></div></div>${e.questions.map((q,i)=>`<article class="exam-question"><div class="scope"><h2>Question ${i+1} · ${esc(q.title)}</h2>${done?`<p><strong>Self-check:</strong> ${esc(q.rubric)}</p>${checklist('exam-'+e.id+'-'+i,'Reproduce the setup, calculations, and contextual conclusion.')}`:''}</div>${q.problems.map(id=>problemHTML(PROB.get(id),Boolean(done),!done)).join('')}</article>`).join('')}`}
function calculatorDownloads(){return `<span class="tag">TI‑84 PLUS CE PYTHON · TI‑BASIC</span><h1>Calculator programs</h1><p>Answers appear first, with the equation and values underneath. ENTER shows more work; CLEAR exits.</p><div class="row"><a class="primary button-link" href="ti84/BME423_TI84_CE_PYTHON.zip" download>Download all programs · ZIP</a><a class="button-link" href="ti84/" target="_blank" rel="noopener">Choose a program & see examples</a><a class="button-link" href="ti84/steps/" target="_blank" rel="noopener">BMSTEPS · follow the equations</a></div><div class="card"><h2>Use the PRGM button</h2><p>The TI‑84 Plus CE Python includes TI‑BASIC. After transferring the .8xp files with TI Connect CE, press <strong>PRGM → EXEC → BMONE → ENTER → ENTER</strong>. The Python app is not needed.</p><p><a href="ti84/#transfer" target="_blank" rel="noopener">Step-by-step transfer instructions</a></p></div><div class="card"><h2>Start with one example</h2>${sourceWorked('onet')}<p><strong>BMONE</strong> checks this one-sample calculation.</p><p>The downloads cover the review’s probability, summary, mean-test, corrected categorical-test, adjusted-comparison and risk/odds calculations. Choose the method using the question’s design and outcome.</p><p>Run the included transfer check on the calculator before relying on the programs. Calculation tests use a software execution harness; physical calculator testing is still needed.</p></div>`}
const REX=[['Normal areas and cutoffs',`pnorm(115, mean=100, sd=15) - pnorm(85, mean=100, sd=15)
# Reference value: approximately 0.6826895
qnorm(0.975, mean=100, sd=15)
# Reference value: approximately 129.3995
pnorm(108, mean=100, sd=20/sqrt(25), lower.tail=FALSE)
# Sample-mean right tail: approximately 0.02275013`,'pnorm gives area; qnorm gives a location. The last command uses SEM because it concerns a mean.'],['Balanced ANOVA',`d <- data.frame(y=c(8,10,12, 10,12,14, 12,14,16),
                group=factor(rep(c("A","B","C"), each=3)))
fit <- aov(y ~ group, data=d)
summary(fit)
# Practice reference: F=3; numerator df=2; denominator df=6.
# Read the Pr(>F) column for the p value.`,'The outcome is left of ~ and group is right of ~. Factor makes the treatment labels categorical.'],['t tests and adjusted cutoffs',`t.test(c(8,10,12), c(12,14,16), var.equal=TRUE)
# var.equal=TRUE requests pooled Student t, not default Welch.
t.test(c(102,104,106,108,110), mu=100)
qt(1 - 0.05/(2*3), df=12)
# Positive two-sided Bonferroni cutoff for three comparisons.
p.adjust(c(0.01,0.03,0.04), method="holm")
# Adjusted p values: 0.03, 0.06, 0.06`,'For post-ANOVA hand comparisons, use the ANOVA within variance and denominator df; the independent two-group example is a separate procedure.'],['Contingency and goodness of fit',`tab <- matrix(c(18,7,6,13), nrow=2, byrow=TRUE)
chisq.test(tab)
# Yates-corrected X-squared approximately 5.577193; df=1.
large <- matrix(c(20,30,30,20,40,10), nrow=3, byrow=TRUE)
chisq.test(large, correct=FALSE)
chisq.test(c(255,125,90), p=c(0.60,0.25,0.15))
# Goodness of fit: X-squared approximately 8.457447; df=2.`,'Keep row/column labels with the table. For a 2×2 table, base R’s default correction matches this course.'],['Course helper names from lsr',`# Functions introduced in the lecture:
# independentSamplesTTest(): two independent groups
# oneSampleTTest(): one sample versus a reference
# posthocPairwiseT(): comparisons after an ANOVA
# goodnessOfFitTest(): counts versus expected probabilities
help("posthocPairwiseT", package="lsr")`, 'These are the package-specific names used in class. The generic base-R procedures above teach the same test/output decisions.'],['Summaries and Normal checks',`x <- c(2,4,4,6,9)
mean(x); var(x); sd(x)
sd(x)/sqrt(length(x))
quantile(x, probs=c(.25,.5,.75), type=7)
qqnorm(x); qqline(x)`,'var() uses n−1. type=7 uses the lecture’s 1 + p(n−1)/100 rank convention. A Q–Q plot checks distribution shape.']];
function rlab(){return `<h1>Read supplied R output</h1><p>The professor said no code writing. Identify the test, statistic, degrees of freedom, and p value, then complete the requested inference or follow-up.</p>${sourceWorked('anovaoutput')}${sourceWorked('output')}<p><button data-topic-quiz="rcode">Practise output interpretation</button></p><div class="card"><h2>Read a statistical table</h2><p>For a two-sided t test, the total α is split across both tails. F and χ² use an upper tail. Match the procedure’s degrees of freedom before reading the value.</p><div class="lookup-fields"><label>Distribution<select id="lookupType"><option value="t">t · two-sided</option><option value="f">F · upper tail</option><option value="chi">χ² · upper tail</option><option value="z">z · two-sided</option></select></label><label>α<input id="lookupAlpha" type="number" value="0.05" step="0.005"></label><label>df / numerator df<input id="lookupDf" type="number" value="12" min="1"></label><label>F denominator df<input id="lookupDf2" type="number" value="20" min="1"></label></div><p><button class="primary" id="lookup">Calculate a practice critical value</button></p><div id="lookupResult" role="status"></div><p class="small muted">This is a practice lookup tool. The original uploaded z, t, F, and χ² tables are available in Statistical tables; print them separately and keep them unannotated.</p></div><details class="card"><summary>R command reference · optional coding practice</summary><p>The review also asks you to understand pnorm and qnorm inputs and outputs. The examples below remain as references; the exam does not require writing programs.</p>${REX.map(([title,code,why],i)=>`<div class="card"><h2>${title}</h2><pre>${esc(code)}</pre>${equationRules(EQUATION_GUIDE.rrefs[i])}<p>${rich(why)}</p></div>`).join('')}</details>`}
function homework(){return `<h1>Homework method map</h1><p>Use the original questions to check the type of work the course asks for. The linked examples teach parallel calculations with their own labeled inputs.</p>${DATA.homework.map(hw=>`<div class="card"><h2>${hw.title}</h2><a href="sources/${hw.id}.pdf" target="_blank" rel="noopener">Open original assignment</a><p class="muted">${esc(hw.note)}${hw.id==='hw2'?' In the review lecture, he expected solutions early Saturday morning.':''}</p>${hw.links.map(([text,key])=>`<p><button data-lesson="${key}">${esc(text)}</button> <button class="tiny" data-problem="${LES.get(key).example}">Parallel worked example</button></p>`).join('')}</div>`).join('')}`}
function sources(){return `<h1>Sources & coverage</h1>${scope()}<div class="row"><button data-view="guidance">What he emphasized</button><button data-view="tables">Uploaded statistical tables</button></div><div class="card"><h2>What is included</h2><p>All 17 supplied PDFs are preserved. All 384 original lecture/review pages are accessible through the collections. Explanations group related pages into topics and teach the method; source images remain unchanged. The 45 teaching topics, ${DATA.problems.length} worked numerical/problem examples, and ${DATA.questions.length} quiz questions use the supplied lecture, review, and homework scope.</p><p>Session 14 and hand-calculated sum-of-squares ANOVA stay out of the default quizzes and core-review route. Clinical-trial concepts from Session 10 remain included. No Session 1 deck was uploaded. The referenced BNP CSV was not uploaded. The original statistical tables and the review transcript are now included in their own workspace sections.</p><p>Arithmetic check: Session 11, PDF page 12 prints a halothane variance/SD that do not match the displayed 8/61 event fraction. The worked example recomputes p̂(1−p̂) and its SE from those counts; the original slide is preserved.</p><p><a href="coverage.json" target="_blank">Page-by-page collection coverage manifest</a></p><button id="export">Download notes & progress</button></div><div class="card"><h2>Learning-design and calculator references</h2><p>Labels and intermediate values remain visible; Version B connects intuition to worked steps, then independent practice. These supports reduce reliance on memory. No special color or font is presented as an ADHD treatment.</p>${V2.research.map(r=>`<p><a href="${r.url}" target="_blank" rel="noopener">${esc(r.title)}</a><br>${esc(r.use)}</p>`).join('')}</div>${DATA.sources.map(s=>`<div class="card"><h3>${esc(s.name)}</h3><p>${s.count} original PDF pages</p><a href="${s.url}" target="_blank" rel="noopener">Open original PDF</a> · <a href="${s.url}" download>Download</a></div>`).join('')}`}
function render(){applyAppearance();nav();document.querySelectorAll('[data-question-version-select]').forEach(el=>el.value=state.questionVersion);document.body.classList.toggle('expanded',view==='viewer'&&viewer.expanded);const screens={home,minimum,guidance,tables,sheetsOriginal,core:()=>pathScreen(true),path:()=>pathScreen(false),lesson:lessonScreen,module:moduleScreen,viewer:viewerScreen,worked:()=>practiceScreen(true),neuroWorked:neuroscienceScreen,practice:()=>practiceScreen(false),formulas,sheets,quizzes:quizMenu,quiz:quizScreen,missed,mock,rlab,homework,sources,calculator:calculatorDownloads,learnNow,checkNow};$('#content').innerHTML=(screens[view]||home)();typesetContent();fitNotesMath();document.querySelectorAll('[data-note]').forEach(sizeNote);document.querySelectorAll('[data-zoom]').forEach(img=>{img.tabIndex=0;img.setAttribute('role','button');img.setAttribute('aria-label','Enlarge '+img.alt)});if(quiz&&!quiz.finished&&view!=='quiz'&&view!=='viewer'){$('#content').insertAdjacentHTML('afterbegin','<p class="no-print"><button id="resumeQuiz">Resume current quiz</button></p>')}}
function parseAnswer(s){s=String(s).trim().replace(/−/g,'-');const m=s.match(/^([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?)\s*(?:\/\s*([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?))?\s*(%)?$/i);if(!m)return NaN;return Number(m[1])/(m[2]?Number(m[2]):1)/(m[3]?100:1)}
function gradeProblem(id){const p=PROB.get(id),value=parseAnswer(state.drafts[id]||'');const prev=state.practice[id];state.practice[id]={correct:Number.isFinite(value)&&Math.abs(value-p.answer)<=p.tolerance,error:!Number.isFinite(value),revealed:prev?.revealed||shown.has(id)||view==='worked'||view==='neuroWorked'};save();render()}
function refreshPercentileChecks(){for(const id of ['percentile','percentile2']){const prev=state.practice[id];if(!prev)continue;const p=PROB.get(id),value=parseAnswer(state.drafts[id]||'');state.practice[id]={...prev,correct:Number.isFinite(value)&&Math.abs(value-p.answer)<=p.tolerance,error:!Number.isFinite(value)}}}
function moveSlide(delta){if('speechSynthesis'in window)speechSynthesis.cancel();viewer.index=Math.max(0,Math.min(viewer.slides.length-1,viewer.index+delta));covered=false;render()}
let timer={running:false,left:25*60,end:0,mode:'Study'};
function setTimer(minutes,mode='Study'){timer={running:false,left:minutes*60,end:0,mode};updateTimer()}
function updateTimer(){if(timer.running)timer.left=Math.max(0,Math.ceil((timer.end-Date.now())/1000));if(timer.left===0)timer.running=false;$('#clock').textContent=String(Math.floor(timer.left/60)).padStart(2,'0')+':'+String(timer.left%60).padStart(2,'0');$('#timerMode').textContent=timer.left===0?'Time is up':timer.mode;$('#timerStart').textContent=timer.running?'Pause':'Start'}
setInterval(updateTimer,1000);
function closeViewer(){const back=viewer.back;covered=false;if('speechSynthesis'in window)speechSynthesis.cancel();go(back==='viewer'?'module':back)}
let lastZoom=null;function closeImage(){$('#modal').classList.add('hidden');lastZoom?.focus()}
function modalImage(img){lastZoom=img;$('#modal').innerHTML=`<div><button id="closeModal">Close ✕</button><img src="${esc(img.src)}" alt="${esc(img.alt)}"></div>`;$('#modal').classList.remove('hidden');$('#closeModal').focus()}
document.addEventListener('input',e=>{if(e.target.dataset.note){state.notes[e.target.dataset.note]=e.target.value;sizeNote(e.target);save()}if(e.target.dataset.response){state.drafts[e.target.dataset.response]=e.target.value;save()}});
document.addEventListener('change',e=>{const x=e.target;if(x.matches('[data-question-version-select]')){state.questionVersion=x.value;const u=new URL(location.href);u.searchParams.set('questionVersion',x.value);history.replaceState(null,'',u);Object.keys(hints).forEach(k=>delete hints[k]);save();render();return}if(x.matches('[data-script-version]')){state.scriptVersion=x.value;save();render();return}if(x.dataset.read){state.read=state.read.filter(v=>v!==x.dataset.read);if(x.checked)state.read.push(x.dataset.read);save()}if(x.dataset.checklist){state.checks=state.checks.filter(v=>v!==x.dataset.checklist);if(x.checked)state.checks.push(x.dataset.checklist);save()}if(x.id==='duration')setTimer(Number(x.value));if(x.id==='slideSelect'){viewer.index=Number(x.value);covered=false;render()}if(x.id==='problemTopic'){problemTopic=x.value;render()}if(x.id==='problemSelect'){selectedProblem=x.value;render()}if(x.id==='neuroTopic'){neuroTopic=x.value;render()}if(x.id==='neuroProblemSelect'){selectedNeuroProblem=x.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='topicSearch'){const s=e.target.value.toLowerCase();document.querySelectorAll('details.lesson').forEach(el=>{el.classList.toggle('hidden',!el.dataset.search.includes(s));if(s&&el.dataset.search.includes(s))el.open=true})}});
document.addEventListener('click',e=>{const img=e.target.closest('[data-zoom]');if(img){modalImage(img);return}const b=e.target.closest('button');if(!b)return;
if(b.dataset.studyStep!==undefined){moveStudyTopic(Number(b.dataset.studyStep));return}if(b.dataset.planGroup!==undefined){const group=Number(b.dataset.planGroup);go('home');$('#study-group-'+group)?.scrollIntoView({block:'start'});return}if(b.dataset.view){go(b.dataset.view);return}if(b.dataset.module){selectedModule=Number(b.dataset.module);go('module');return}if(b.dataset.lesson){selectedLesson=b.dataset.lesson;const group=b.dataset.studyGroup===undefined?null:Number(b.dataset.studyGroup);studyGroup=Number.isInteger(group)&&DAYS[group]?.[2].includes(selectedLesson)?group:null;go('lesson');return}if(b.dataset.theme){state.theme=b.dataset.theme;applyAppearance();save();return}if(b.dataset.font){state.font=Math.max(15,Math.min(26,state.font+Number(b.dataset.font)));applyAppearance();save();return}
if(b.dataset.problem){selectedProblem=b.dataset.problem;problemTopic='all';go('worked');return}if(b.dataset.practiceTopic){const l=LES.get(b.dataset.practiceTopic);problemTopic=DATA.problems.some(p=>p.topic===l.id)?l.id:PROB.get(l.example).topic;selectedProblem=l.example;go('practice');return}
if(b.dataset.openSlide){const[mid,page]=b.dataset.openSlide.split(':').map(Number);const slides=makeModuleSlides(mid);openViewer(slides,slides.findIndex(s=>s.page===page));return}if(b.dataset.moduleView){openViewer(makeModuleSlides(selectedModule),0,b.dataset.moduleView==='expanded');return}if(b.dataset.viewerSet){const ls=DATA.lessons.filter(l=>b.dataset.viewerSet==='core'?l.core:l.id!=='power'&&l.id!=='anovaSS');openViewer(ls.map(l=>({topic:l.id,module:l.refs[0].module,page:l.refs[0].page,label:l.title})));return}
if(b.dataset.grade){gradeProblem(b.dataset.grade);return}if(b.dataset.hint){hints[b.dataset.hint]=Math.min(problemSteps(PROB.get(b.dataset.hint)).length,(hints[b.dataset.hint]||0)+1);render();return}if(b.dataset.solution){shown.add(b.dataset.solution);state.practice[b.dataset.solution]={...(state.practice[b.dataset.solution]||{}),revealed:true};save();render();return}
if(b.dataset.quizModule){startQuiz('module',b.dataset.quizModule);return}if(b.dataset.topicQuiz){startQuiz('topic',null,b.dataset.topicQuiz);return}if(b.dataset.start){startQuiz(b.dataset.start);return}if(b.dataset.answer!==undefined){answer(Number(b.dataset.answer));return}if(b.dataset.exam){examId=b.dataset.exam;render();return}
switch(b.id){case'openSide':state.side=false;applyAppearance();save();break;case'closeSide':state.side=true;applyAppearance();save();break;case'toggleSide':state.side=!state.side;applyAppearance();save();break;case'timerStart':if(timer.running){timer.left=Math.max(0,Math.ceil((timer.end-Date.now())/1000));timer.running=false}else{timer.end=Date.now()+timer.left*1000;timer.running=true}updateTimer();break;case'timerReset':setTimer(Number($('#duration').value));break;case'timerBreak':setTimer(5,'Break');break;case'exitViewer':closeViewer();break;case'prevSlide':moveSlide(-1);break;case'nextSlide':moveSlide(1);break;case'coverTranscript':case'revealTranscript':covered=!covered;render();break;case'speak':if('speechSynthesis'in window&&$('#spoken')){speechSynthesis.cancel();const spoken=$('#spoken').cloneNode(true);spoken.querySelectorAll('.katex-mathml').forEach(el=>el.remove());const u=new SpeechSynthesisUtterance(spoken.innerText);u.rate=.9;speechSynthesis.speak(u)}break;case'stopSpeak':if('speechSynthesis'in window)speechSynthesis.cancel();break;case'closeModal':closeImage();break;case'openTopics':document.querySelectorAll('details.lesson:not(.hidden)').forEach(d=>d.open=true);break;case'closeTopics':document.querySelectorAll('details.lesson').forEach(d=>d.open=false);break;case'newNeuroProblem':{const p=PROB.get(selectedNeuroProblem),choices=NEURO_WORKED.problems.filter(q=>q.topic===p.topic&&q.id!==p.id);if(choices.length)selectedNeuroProblem=shuffle(choices)[0].id;render();break}case'newProblem':{const p=PROB.get(selectedProblem);const choices=problemPool().filter(q=>q.topic===p.topic&&q.id!==p.id);if(choices.length)selectedProblem=shuffle(choices)[0].id;render();break}case'resumeQuiz':go('quiz');break;case'revealQ':answer(null);break;case'uncertain':{let id=quiz.items[quiz.index].id;if(!state.missed.includes(id))state.missed.push(id);save();render();break}case'prevQ':quiz.index--;render();break;case'nextQ':case'skipQ':if(quiz.index===quiz.items.length-1)quiz.finished=true;else quiz.index++;render();window.scrollTo(0,0);break;case'startMock':setTimer(90,'Practice exam');timer.running=true;timer.end=Date.now()+5400000;updateTimer();break;case'finishMock':state.examDone[examStateKey(examId)]=true;save();render();break;case'resetMock':state.examDone[examStateKey(examId)]=false;save();render();break;case'print':window.print();break;case'export':{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='BME423-notes-and-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break}case'lookup':{let alpha=Number($('#lookupAlpha').value),df=Number($('#lookupDf').value),df2=Number($('#lookupDf2').value),type=$('#lookupType').value;if(!(alpha>0&&alpha<1&&df>0&&df2>0)){$('#lookupResult').textContent='Use 0<α<1 and positive degrees of freedom.';break}const v=type==='t'?jStat.studentt.inv(1-alpha/2,df):type==='f'?jStat.centralF.inv(1-alpha,df,df2):type==='chi'?jStat.chisquare.inv(1-alpha,df):jStat.normal.inv(1-alpha/2,0,1);$('#lookupResult').innerHTML=`${equationRules([type==='t'?'tlookup':type==='f'?'flookup':type==='chi'?'chilookup':'zlookup'])}<div class="formula">Critical ${esc(type)} = ${v.toFixed(6)}</div><p>${type==='t'||type==='z'?'Two-sided: each tail has area α/2.':'Upper-tail area is α.'} Compare the statistic with the matching cutoff.</p>`;typesetContent();break}}
});
document.addEventListener('keydown',e=>{if(!$('#modal').classList.contains('hidden')){if(e.key==='Escape')closeImage();if(e.key==='Tab'){e.preventDefault();$('#closeModal').focus()}return}if(document.activeElement.matches('[data-zoom]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();modalImage(document.activeElement);return}if(e.key==='Escape'&&view==='viewer'){closeViewer();return}if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(view==='viewer'){if(e.key==='ArrowRight'){e.preventDefault();moveSlide(1)}if(e.key==='ArrowLeft'){e.preventDefault();moveSlide(-1)}}if(view==='quiz'&&quiz&&!quiz.finished&&!quiz.answers[quiz.index]){let i='abcd'.indexOf(e.key.toLowerCase());if(i<0)i='1234'.indexOf(e.key);if(i>=0){e.preventDefault();answer(quiz.items[quiz.index].order[i])}}});
const routeParams=new URLSearchParams(location.search);const initialRoute=routeParams.get('view');if(NAV.some(([key])=>key===initialRoute))view=initialRoute;const requestedQuestionVersion=routeParams.get('questionVersion');if(['D','C'].includes(requestedQuestionVersion))state.questionVersion=requestedQuestionVersion;const requestedProblem=routeParams.get('problem');if(NEURO_WORKED.questions[requestedProblem]){selectedNeuroProblem=requestedProblem;view='neuroWorked'}else if(PROB.has(requestedProblem))selectedProblem=requestedProblem;else if(versionD())selectedProblem=VERSION_D.examples.summary;
refreshPercentileChecks();render();updateTimer();
